var replaceDigits = function(s) {
    const buf = s.split('');
    for (let i = 1; i < buf.length; i += 2)
        buf[i] = String.fromCharCode(buf[i - 1].charCodeAt(0) + Number(buf[i]));
    return buf.join('');
};

