class Solution {
    public String replaceDigits(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            sb.append(i % 2 == 1 ? (char) (s.charAt(i - 1) + (c - '0')) : c);
        }
        return sb.toString();
    }
}

